// `foo/index.md` publishes as `foo/`, everything else as `foo/bar.html`. Anchor
// the index match on the leading slash so `guide/myindex.md` keeps its name.
const pageUrl = (relativePath: string) =>
  `${siteUrl}/${relativePath}`
    .replace(/\/index\.md$/, "/")
