import { createHash } from "node:crypto";
import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { Resvg } from "@resvg/resvg-js";

const fontFile = fileURLToPath(
  new URL("./fonts/SpaceGrotesk.ttf", import.meta.url),
);
const logo = readFileSync(
  new URL("../public/logo-dark.svg", import.meta.url),
  "utf8",
);
const escapeXml = (value) =>
  String(value).replace(
    /[<>&"']/g,
    (c) =>
      ({
        "<": "&lt;",
        ">": "&gt;",
        "&": "&amp;",
        '"': "&quot;",
        "'": "&apos;",
      })[c],
  );

const fontOptions = { fontFiles: [fontFile], loadSystemFonts: false };
const widths = new Map();
/** Measure visible text bounds using the same font and renderer as the card. */
export function textWidth(text, size) {
  const key = `${size}:${text}`;
  if (!widths.has(key)) {
    const measure = new Resvg(
      `<svg xmlns="http://www.w3.org/2000/svg" width="10000" height="200"><text y="100" font-family="Space Grotesk" font-size="${size}">${escapeXml(text)}</text></svg>`,
      { font: fontOptions },
    );
    widths.set(key, measure.innerBBox()?.width ?? 0);
  }
  return widths.get(key);
}

/** Wrap measured text within the title column, splitting long CLI names when needed. */
export function wrapTitle(title, size = 62, width = 720) {
  const words = String(title)
    .trim()
    .split(/\s+/)
    .flatMap((word) => {
      const chunks = [];
      let chunk = "";
      for (const letter of word) {
        if (chunk && textWidth(chunk + letter, size) > width) {
          chunks.push(chunk);
          chunk = "";
        }
        chunk += letter;
      }
      if (chunk) chunks.push(chunk);
      return chunks;
    });
  const lines = [];
  let line = "";
  for (const word of words) {
    if (line && textWidth(`${line} ${word}`, size) > width) {
      lines.push(line);
      line = word;
    } else line = line ? `${line} ${word}` : word;
  }
  if (line) lines.push(line);
  return lines;
}

/** Render a title card and address it by the final PNG bytes, including renderer changes. */
export function socialCard(title) {
  let size = 62;
  let lines = wrapTitle(title, size);
  if (lines.length > 4) {
    size = 54;
    lines = wrapTitle(title, size);
  }
  if (lines.length > 4) {
    lines = lines.slice(0, 4);
    while (textWidth(`${lines[3]}…`, size) > 720)
      lines[3] = Array.from(lines[3]).slice(0, -1).join("");
    lines[3] += "…";
  }
  const start = 298 - ((lines.length - 1) * (size + 14)) / 2;
  const heading = lines
    .map(
      (line, i) =>
        `<text x="64" y="${start + i * (size + 14)}" font-size="${size}" fill="#f4eee3">${escapeXml(line)}</text>`,
    )
    .join("");
  const svg = `<svg xmlns="http://www.w3.org/2000/svg" xmlns:xlink="http://www.w3.org/1999/xlink" width="1200" height="630" viewBox="0 0 1200 630">
    <rect width="1200" height="630" fill="#171417"/>
    <rect width="1200" height="8" fill="#c75b7a"/>
    <g font-family="Space Grotesk">
      <text x="64" y="85" font-size="30" fill="#c75b7a">mise / docs</text>
      ${heading}
      <path d="M64 508 H1136" stroke="#3d3540"/>
      <text x="64" y="564" font-size="26" fill="#c2b6a4">mise.jdx.dev</text>
      <text x="1136" y="564" text-anchor="end" font-size="26" fill="#c75b7a">mise</text>
    </g>
    <image x="855" y="145" width="280" height="280" xlink:href="data:image/svg+xml;base64,${Buffer.from(logo).toString("base64")}"/>
  </svg>`;
  const png = new Resvg(svg, { font: fontOptions }).render().asPng();
  const hash = createHash("sha256").update(png).digest("hex").slice(0, 16);
  return { svg, png, path: `social/${hash}.png` };
}

/** Write the already rendered card to the VitePress output directory. */
export function writeSocialCard(outDir, card) {
  mkdirSync(resolve(outDir, "social"), { recursive: true });
  writeFileSync(resolve(outDir, card.path), card.png);
}
import assert from "node:assert/strict";
import { createHash } from "node:crypto";
import { mkdtempSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import test from "node:test";
import { spawnSync } from "node:child_process";
import { fileURLToPath } from "node:url";
import {
  socialCard,
  textWidth,
  wrapTitle,
  writeSocialCard,
} from "./social-images.mjs";

test("long headings and command names stay out of the logo column", () => {
  for (const title of [
    "W".repeat(120),
    "Machine-wide compilation scheduling and memory budgets",
    "mise help --verbose",
  ]) {
    const lines = wrapTitle(title);
    assert.ok(lines.length > 0);
    for (const line of lines) assert.ok(textWidth(line, 62) <= 720, line);
  }
});

test("escapes title markup and gives changed content a new image URL", () => {
  const first = socialCard('Rust & C++ <build> "cache"');
  assert.match(first.svg, /Rust &amp; C\+\+/);
  assert.ok(!first.svg.includes("<build>"));
  assert.equal(first.path, socialCard('Rust & C++ <build> "cache"').path);
  assert.notEqual(first.path, socialCard("Another page").path);
});

test("renders a self-contained 1200 by 630 PNG", () => {
  const dir = mkdtempSync(join(tmpdir(), "mise-social-"));
  try {
    const card = socialCard("Get started");
    writeSocialCard(dir, card);
    const png = readFileSync(join(dir, card.path));
    assert.deepEqual(
      [...png.subarray(0, 8)],
      [137, 80, 78, 71, 13, 10, 26, 10],
    );
    assert.equal(png.readUInt32BE(16), 1200);
    assert.equal(png.readUInt32BE(20), 630);
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
});

test("final long-title layout shrinks, truncates, and stays inside the title column", () => {
  const card = socialCard("Very long documentation heading ".repeat(30));
  const lines = [
    ...card.svg.matchAll(
      /<text x="64" y="([^"]+)" font-size="(\d+)" fill="#f4eee3">([^<]*)<\/text>/g,
    ),
  ];
  assert.equal(lines.length, 4);
  assert.ok(lines.at(-1)[3].endsWith("…"));
  for (const [, y, size, text] of lines) {
    assert.equal(Number(size), 54);
    assert.ok(textWidth(text, Number(size)) <= 720);
    assert.ok(Number(y) - Number(size) > 100);
    assert.ok(Number(y) < 508);
  }
});

test("image URL hashes exactly the emitted PNG", () => {
  const card = socialCard("Cache invalidation");
  const hash = createHash("sha256").update(card.png).digest("hex").slice(0, 16);
  assert.equal(card.path, `social/${hash}.png`);
});

test("built-page checks reject swapped images and empty alt text", () => {
  const dir = mkdtempSync(join(tmpdir(), "social-validation-"));
  const first = socialCard("First page");
  const second = socialCard("Second page");
  const page = (title, card, alt = title + " — mise docs") => `
    <meta property="og:title" content="${title} | mise-en-place">
    <meta name="twitter:title" content="${title} | mise-en-place">
