    transformHead({ pageData, title, description, siteConfig }) {
      const heading =
        pageData.relativePath === "index.md"
          ? "Dev tools, environments, and tasks"
          : pageData.title || "mise";
      const card = socialCard(heading);
      writeSocialCard(siteConfig.outDir, card);
      const image = new URL(card.path, `${siteUrl}/`).toString();
      const imageAlt = `${heading} — mise docs`;
      const url = pageUrl(pageData.relativePath);

      return [
        ["meta", { property: "og:url", content: url }],
        ["meta", { property: "og:image", content: image }],
        ["meta", { property: "og:image:alt", content: imageAlt }],
        ["meta", { name: "twitter:image", content: image }],
        ["meta", { name: "twitter:image:alt", content: imageAlt }],
        ["meta", { property: "og:title", content: title }],
        ["meta", { property: "og:description", content: description }],
        ["meta", { name: "twitter:title", content: title }],
        ["meta", { name: "twitter:description", content: description }],
        [
          "script",
          { type: "application/ld+json" },
          ldJson({
            "@context": "https://schema.org",
            "@type": "WebPage",
            name: title,
            description,
            url,
            isPartOf: {
              "@type": "WebSite",
              name: "mise-en-place",
              url: siteUrl,
            },
          }),
        ],
      ];
    },
    transformPageData(pageData) {
      const canonicalUrl = pageUrl(pageData.relativePath);

      pageData.frontmatter.head ??= [];
      pageData.frontmatter.head.push([
        "link",
        { rel: "canonical", href: canonicalUrl },
      ]);
      pageData.frontmatter.head.push([
        "link",
        {
          rel: "sitemap",
          href: "https://mise.jdx.dev/sitemap.xml",
          type: "application/xml",
          title: "Sitemap",
        },
      ]);
    },
    transformHtml(code) {
      return code.replace(
        /<script id="check-dark-mode">/,
        '<script id="check-dark-mode" data-cfasync="false">',
      );
    },
    buildEnd(siteConfig) {
      assertNoEmptyDocPages(siteConfig.outDir);
    },
  }),
);
# Social previews

The docs build generates a 1200×630 PNG per page from its title and mise's
existing logo. The homepage uses a short product description. Images are
rendered locally with resvg and the bundled OFL-licensed Space Grotesk font;
no rendering service or system font is required. Image URLs include a content
hash of the final PNG bytes so title, artwork, font, and renderer changes get a
new URL.

`docs:build` tests text wrapping and PNG rendering, then checks the built HTML
for matching Open Graph/Twitter metadata and the exact image expected from each
page title. Regression tests reject swapped images and empty alt text. Edit
`social-images.mjs` to adjust colors or layout.

